import boto3

def get_translate_client():
    return boto3.client('translate')

class TranslationRequest:
    def __init__(self, text, source_lang, target_lang):
        self.text = text
        self.source_lang = source_lang
        self.target_lang = target_lang

class TranslationResponse:
    def __init__(self, translated_text):
        self.translated_text = translated_text

from translation_client import get_translate_client

def generate_localized_audio(text, target_lang):
    client = get_translate_client()
    response = client.synthesize_speech(
        Text=text,
        OutputFormat='mp3',
        VoiceId='Joanna',
        LanguageCode=target_lang
    )
    return response['AudioStream'].read()
